const P: MessageTreeNode = { id: "P", workspaceSlug: "wa", cwd: "/ws/a" }
const A: MessageTreeNode = { id: "A", parentSessionId: "P", workspaceSlug: "wa", cwd: "/ws/a" }
const B: MessageTreeNode = { id: "B", parentSessionId: "P", workspaceSlug: "wb", cwd: "/ws/b" }
const G: MessageTreeNode = { id: "G", parentSessionId: "A", workspaceSlug: "wa", cwd: "/ws/a" }
const H: MessageTreeNode = { id: "H", parentSessionId: "B", workspaceSlug: "wb", cwd: "/ws/b" }
const C: MessageTreeNode = { id: "C", workspaceSlug: "wc", cwd: "/ws/c" }
const D: MessageTreeNode = { id: "D", workspaceSlug: "wa", cwd: "/ws/a" }
const X: MessageTreeNode = { id: "X", workspaceSlug: "wx", cwd: "/ws/x" }

const nodes: Record<string, MessageTreeNode> = { P, A, B, G, H, C, D, X }
const senders: Record<string, Principal> = {
  ...Object.fromEntries(Object.entries(nodes).map(([id, session]) => [id, { kind: "session", session }])),
  operator: { kind: "operator", via: "anonymous-local" },
  system: { kind: "system" },
  relay: { kind: "relay", boxSessionId: "box1", parentSessionId: "P" },
}

const pairs: Array<[string, string]> = [
  ["P", "A"], ["A", "P"], ["P", "G"], ["G", "P"], ["A", "B"], ["B", "A"],
  ["G", "H"], ["H", "G"], ["C", "P"], ["D", "C"], ["D", "P"], ["C", "D"],
  ["operator", "P"], ["operator", "G"], ["operator", "C"], ["system", "A"],
  ["relay", "P"], ["relay", "A"], ["A", "G"], ["G", "A"], ["A", "H"], ["B", "G"],
  ["X", "C"], ["C", "X"], ["X", "P"], ["A", "A"], ["P", "P"],
]

const workspaceOfCwd = (cwd: string) =>
  cwd === "/ws/a" ? "wa" : cwd === "/ws/b" ? "wb" : cwd === "/ws/c" ? "wc" : cwd === "/ws/x" ? "wx" : undefined

const settings: Array<{ name: string; ctx: PermissionContext }> = [
  { name: "siblings-on-same-workspace-default", ctx: { messaging: { allowSiblings: true } } },
  { name: "siblings-off-same-workspace-off", ctx: { messaging: { allowSiblings: false, allowSameWorkspace: false, agentInterrupt: "allow" } } },
  { name: "peer-group-wa-wc-siblings-on", ctx: { messaging: { allowSiblings: true, allowSameWorkspace: false, peerGroups: [["wa", "wc"]], agentInterrupt: "allow" } } },
  { name: "verified-binding", ctx: { messaging: { allowSiblings: false, allowSameWorkspace: true, peerBinding: "verified", peerGroups: [["wa", "wx"]], agentInterrupt: "deny" }, workspaceOfCwd } },
  { name: "verified-binding-no-resolver", ctx: { messaging: { allowSiblings: true, peerBinding: "verified", peerGroups: [["wa", "wx"]], agentInterrupt: "allow" } } },
  { name: "peer-group-wb-wx-same-off", ctx: { messaging: { allowSiblings: false, allowSameWorkspace: false, peerGroups: [["wb", "wx"]], agentInterrupt: "deny" } } },
]

const POLICIES: Array<[string, PermissionContext["policy"] | undefined]> = [
  ["no policy", undefined],
  ["an empty policy", { inputs: [] }],
  ["a non-matching allow grant", { inputs: [{ principal: "*", effect: "allow", actions: [{ action: "session:message", scope: "workspace:nowhere" }] }] }],
]

describe("messaging ACL parity: explicit allow grants change nothing unless they match", () => {
  it("reproduces the captured table under all three contexts", () => {
    const expected = new Map(TABLE.map(row => [row[0], row]))
    for (const { name, ctx } of settings) {
      for (const action of ["session.message", "session.message.interrupt"] as const) {
        for (const [senderId, recipientId] of pairs) {
          const key = `${name}|${action}|${senderId}->${recipientId}`
          const row = expected.get(key)
          expect(row, key).toBeDefined()
          for (const [label, policy] of POLICIES) {
            const d = decide(senders[senderId]!, action, { kind: "session", session: nodes[recipientId]! }, {
              ...ctx,
              ...(policy ? { policy } : {}),
            })
            expect(
              [d.allow, d.rule, d.relation ?? null, d.relations ?? null, d.peerVerified ?? null, d.reason],
              `${key} [${label}]`,
            ).toEqual(row!.slice(1))
          }
        }
      }
    }
  })
})
